-- Create "agents" table
CREATE TABLE "agents" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "name" character varying NOT NULL, "description" character varying NOT NULL DEFAULT '', "system_prompt" text NOT NULL DEFAULT '', "opening" character varying NOT NULL DEFAULT '', "model_id" bigint NULL, "kb_ids" jsonb NULL, "tool_ids" jsonb NULL, "max_steps" bigint NOT NULL DEFAULT 5, "published_version" bigint NOT NULL DEFAULT 0, "draft_dirty" boolean NOT NULL DEFAULT true, "created_by" bigint NOT NULL, "deleted_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "agent_org_id_deleted_at" to table: "agents"
CREATE INDEX "agent_org_id_deleted_at" ON "agents" ("org_id", "deleted_at");
-- Create "agent_versions" table
CREATE TABLE "agent_versions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" bigint NOT NULL, "agent_id" bigint NOT NULL, "version" bigint NOT NULL, "config" jsonb NOT NULL, "note" character varying NOT NULL DEFAULT '', "published_by" bigint NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "agentversion_agent_id_version" to table: "agent_versions"
CREATE UNIQUE INDEX "agentversion_agent_id_version" ON "agent_versions" ("agent_id", "version");
